template<> __declspec(noinline) bool CDefClassBase::GetSubDef<CCreatureDef>(CDefPointer<const CCreatureDef>* out) const
{
    const CSubDefInfo* index;
    { CCharString name("CCreatureDef",-1); index=GetPSubDefInfo(name); }
